INSERT INTO public.course_catalog (id, slug, title, short_description, long_description, level, category, order_index, is_published)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations)
VALUES
  ('unit-street-a1-02-01', 'lesson-street-a1-02', 1, 'sentence', 'Are you free this weekend?', 'Você tá livre no fim de semana?', '/ɑːr juː friː ðɪs ˈwiːkɛnd/', '"Free" aqui é "disponível", não "grátis".', '[{"start":0,"end":3,"role":"predicate_verb","surface":"Are"},{"start":4,"end":7,"role":"subject","surface":"you"},{"start":8,"end":12,"role":"predicate_adj","surface":"free"},{"start":13,"end":26,"role":"adverbial","surface":"this weekend?"}]'::jsonb, '[{"surface":"Are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"free","pos":"adjective","ipa":"/friː/","gloss":"livre, disponível"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"weekend","pos":"noun","ipa":"/ˈwiːkɛnd/","gloss":"fim de semana"}]'::jsonb),
  ('unit-street-a1-02-02', 'lesson-street-a1-02', 2, 'sentence', 'Wanna grab a bite after work?', 'Bora comer alguma coisa depois do trabalho?', '/ˈwɑːnə ɡræb ə baɪt ˈæftər wɜːrk/', '"Wanna" = "want to". "Grab a bite" = comer algo rápido.', '[{"start":0,"end":10,"role":"predicate_verb","surface":"Wanna grab"},{"start":11,"end":17,"role":"direct_object","surface":"a bite"},{"start":18,"end":29,"role":"adverbial","surface":"after work?"}]'::jsonb, '[{"surface":"Wanna","pos":"verb","ipa":"/ˈwɑːnə/","gloss":"quer (want to)"},{"surface":"grab","pos":"verb","ipa":"/ɡræb/","gloss":"pegar, comer algo rápido"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"bite","pos":"noun","ipa":"/baɪt/","gloss":"mordida; algo para comer"},{"surface":"after","pos":"preposition","ipa":"/ˈæftər/","gloss":"depois de"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"}]'::jsonb),
  ('unit-street-a1-02-03', 'lesson-street-a1-02', 3, 'sentence', 'Sure, I''m down. What time?', 'Claro, tô dentro. Que horas?', '/ʃʊr aɪm daʊn wʌt taɪm/', '"I''m down" = topo, tô dentro.', '[{"start":0,"end":5,"role":"discourse_marker","surface":"Sure,"},{"start":6,"end":9,"role":"subject","surface":"I''m"},{"start":10,"end":15,"role":"predicate_adj","surface":"down."},{"start":16,"end":26,"role":"adverbial","surface":"What time?"}]'::jsonb, '[{"surface":"Sure","pos":"adjective","ipa":"/ʃʊr/","gloss":"claro; certo"},{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"down","pos":"adjective","ipa":"/daʊn/","gloss":"dentro, topando (gíria)"},{"surface":"What","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"}]'::jsonb),
  ('unit-street-a1-02-04', 'lesson-street-a1-02', 4, 'sentence', 'Let''s meet at seven.', 'Vamos nos encontrar às sete.', '/lɛts miːt æt ˈsɛvən/', '"Let''s" é o jeito natural de sugerir algo junto.', '[{"start":0,"end":10,"role":"predicate_verb","surface":"Let''s meet"},{"start":11,"end":20,"role":"adverbial","surface":"at seven."}]'::jsonb, '[{"surface":"Let''s","pos":"verb","ipa":"/lɛts/","gloss":"vamos"},{"surface":"meet","pos":"verb","ipa":"/miːt/","gloss":"encontrar"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"seven","pos":"numeral","ipa":"/ˈsɛvən/","gloss":"sete"}]'::jsonb),
  ('unit-street-a1-02-05', 'lesson-street-a1-02', 5, 'sentence', 'I can''t make it tonight.', 'Não vou conseguir ir hoje à noite.', '/aɪ kænt meɪk ɪt təˈnaɪt/', '"Make it" = conseguir comparecer ou chegar.', '[{"start":0,"end":1,"role":"subject","surface":"I"},{"start":2,"end":15,"role":"predicate_verb","surface":"can''t make it"},{"start":16,"end":24,"role":"adverbial","surface":"tonight."}]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"can''t","pos":"auxiliary verb","ipa":"/kænt/","gloss":"não poder"},{"surface":"make","pos":"verb","ipa":"/meɪk/","gloss":"fazer; conseguir ir (make it)"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"tonight","pos":"adverb","ipa":"/təˈnaɪt/","gloss":"hoje à noite"}]'::jsonb),
  ('unit-street-a1-02-06', 'lesson-street-a1-02', 6, 'sentence', 'Can we do it tomorrow instead?', 'Dá pra gente fazer amanhã em vez disso?', '/kæn wiː duː ɪt təˈmɑːroʊ ɪnˈstɛd/', '"Instead" no fim = no lugar disso.', '[{"start":0,"end":3,"role":"predicate_verb","surface":"Can"},{"start":4,"end":6,"role":"subject","surface":"we"},{"start":7,"end":12,"role":"predicate_verb","surface":"do it"},{"start":13,"end":30,"role":"adverbial","surface":"tomorrow instead?"}]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"tomorrow","pos":"adverb","ipa":"/təˈmɑːroʊ/","gloss":"amanhã"},{"surface":"instead","pos":"adverb","ipa":"/ɪnˈstɛd/","gloss":"em vez disso"}]'::jsonb),
  ('unit-street-a1-02-07', 'lesson-street-a1-02', 7, 'sentence', 'I''ll text you the address.', 'Eu te mando o endereço por mensagem.', '/aɪl tɛkst juː ðə ˈædrɛs/', '"Text" também é verbo: mandar mensagem.', '[{"start":0,"end":4,"role":"subject","surface":"I''ll"},{"start":5,"end":13,"role":"predicate_verb","surface":"text you"},{"start":14,"end":26,"role":"direct_object","surface":"the address."}]'::jsonb, '[{"surface":"I''ll","pos":"pronoun","ipa":"/aɪl/","gloss":"eu vou"},{"surface":"text","pos":"verb","ipa":"/tɛkst/","gloss":"mandar mensagem"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"address","pos":"noun","ipa":"/ˈædrɛs/","gloss":"endereço"}]'::jsonb),
  ('unit-street-a1-02-08', 'lesson-street-a1-02', 8, 'sentence', 'Don''t be late this time!', 'Não se atrasa dessa vez!', '/doʊnt biː leɪt ðɪs taɪm/', 'Imperativo negativo com "don''t".', '[{"start":0,"end":8,"role":"predicate_verb","surface":"Don''t be"},{"start":9,"end":13,"role":"predicate_adj","surface":"late"},{"start":14,"end":24,"role":"adverbial","surface":"this time!"}]'::jsonb, '[{"surface":"Don''t","pos":"auxiliary verb","ipa":"/doʊnt/","gloss":"não"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"late","pos":"adjective","ipa":"/leɪt/","gloss":"atrasado"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"}]'::jsonb),
  ('unit-street-a1-02-09', 'lesson-street-a1-02', 9, 'sentence', 'I''m on my way.', 'Tô a caminho.', '/aɪm ɑːn maɪ weɪ/', 'Frase fixa para avisar que já saiu.', '[{"start":0,"end":3,"role":"subject","surface":"I''m"},{"start":4,"end":14,"role":"predicate_adj","surface":"on my way."}]'::jsonb, '[{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"way","pos":"noun","ipa":"/weɪ/","gloss":"caminho; jeito"}]'::jsonb),
  ('unit-street-a1-02-10', 'lesson-street-a1-02', 10, 'sentence', 'Running late, be there in ten.', 'Tô atrasado, chego em dez minutos.', '/ˈrʌnɪŋ leɪt biː ðɛr ɪn tɛn/', 'Mensagem curta: o sujeito "I''m" some na fala informal.', '[{"start":0,"end":13,"role":"predicate_adj","surface":"Running late,"},{"start":14,"end":22,"role":"predicate_verb","surface":"be there"},{"start":23,"end":30,"role":"adverbial","surface":"in ten."}]'::jsonb, '[{"surface":"Running","pos":"verb","ipa":"/ˈrʌnɪŋ/","gloss":"ficando (running late)"},{"surface":"late","pos":"adjective","ipa":"/leɪt/","gloss":"atrasado"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"there","pos":"adverb","ipa":"/ðɛr/","gloss":"lá"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"ten","pos":"numeral","ipa":"/tɛn/","gloss":"dez"}]'::jsonb)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations)
VALUES
  ('unit-street-a1-03-01', 'lesson-street-a1-03', 1, 'sentence', 'No way, are you serious?', 'Não acredito, cê tá falando sério?', '/noʊ weɪ ɑːr juː ˈsɪriəs/', '"No way" mostra surpresa.', '[{"start":0,"end":7,"role":"discourse_marker","surface":"No way,"},{"start":8,"end":11,"role":"predicate_verb","surface":"are"},{"start":12,"end":15,"role":"subject","surface":"you"},{"start":16,"end":24,"role":"predicate_adj","surface":"serious?"}]'::jsonb, '[{"surface":"No","pos":"determiner","ipa":"/noʊ/","gloss":"nenhum; não"},{"surface":"way","pos":"noun","ipa":"/weɪ/","gloss":"caminho; jeito"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"serious","pos":"adjective","ipa":"/ˈsɪriəs/","gloss":"sério"}]'::jsonb),
  ('unit-street-a1-03-02', 'lesson-street-a1-03', 2, 'sentence', 'That''s so cool!', 'Que massa!', '/ðæts soʊ kuːl/', '"Cool" = legal, massa.', '[{"start":0,"end":6,"role":"subject","surface":"That''s"},{"start":7,"end":15,"role":"predicate_adj","surface":"so cool!"}]'::jsonb, '[{"surface":"That''s","pos":"pronoun","ipa":"/ðæts/","gloss":"isso é"},{"surface":"so","pos":"adverb","ipa":"/soʊ/","gloss":"tão"},{"surface":"cool","pos":"adjective","ipa":"/kuːl/","gloss":"legal, massa"}]'::jsonb),
  ('unit-street-a1-03-03', 'lesson-street-a1-03', 3, 'sentence', 'Tell me about it.', 'Nem me fala.', '/tɛl miː əˈbaʊt ɪt/', 'Apesar da forma, significa "concordo totalmente".', '[{"start":0,"end":7,"role":"predicate_verb","surface":"Tell me"},{"start":8,"end":17,"role":"adverbial","surface":"about it."}]'::jsonb, '[{"surface":"Tell","pos":"verb","ipa":"/tɛl/","gloss":"contar, dizer"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"about","pos":"preposition","ipa":"/əˈbaʊt/","gloss":"sobre"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"}]'::jsonb),
  ('unit-street-a1-03-04', 'lesson-street-a1-03', 4, 'sentence', 'I know, right?', 'Né? Também acho!', '/aɪ noʊ raɪt/', 'Concordar com empolgação.', '[{"start":0,"end":1,"role":"subject","surface":"I"},{"start":2,"end":7,"role":"predicate_verb","surface":"know,"},{"start":8,"end":14,"role":"discourse_marker","surface":"right?"}]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"know","pos":"verb","ipa":"/noʊ/","gloss":"saber"},{"surface":"right","pos":"adverb","ipa":"/raɪt/","gloss":"bem; né? (right?)"}]'::jsonb),
  ('unit-street-a1-03-05', 'lesson-street-a1-03', 5, 'sentence', 'Fair enough.', 'Justo.', '/fɛr ɪˈnʌf/', 'Aceitar o argumento do outro.', '[{"start":0,"end":12,"role":"discourse_marker","surface":"Fair enough."}]'::jsonb, '[{"surface":"Fair","pos":"adjective","ipa":"/fɛr/","gloss":"justo"},{"surface":"enough","pos":"adverb","ipa":"/ɪˈnʌf/","gloss":"o bastante"}]'::jsonb),
  ('unit-street-a1-03-06', 'lesson-street-a1-03', 6, 'sentence', 'I''m not sure about that.', 'Não tenho certeza disso.', '/aɪm nɑːt ʃʊr əˈbaʊt ðæt/', 'Discordar de leve, sem ser grosso.', '[{"start":0,"end":3,"role":"subject","surface":"I''m"},{"start":4,"end":12,"role":"predicate_adj","surface":"not sure"},{"start":13,"end":24,"role":"adverbial","surface":"about that."}]'::jsonb, '[{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"sure","pos":"adjective","ipa":"/ʃʊr/","gloss":"claro; certo"},{"surface":"about","pos":"preposition","ipa":"/əˈbaʊt/","gloss":"sobre"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"}]'::jsonb),
  ('unit-street-a1-03-07', 'lesson-street-a1-03', 7, 'sentence', 'That makes sense.', 'Faz sentido.', '/ðæt meɪks sɛns/', 'Mostrar que entendeu.', '[{"start":0,"end":4,"role":"subject","surface":"That"},{"start":5,"end":10,"role":"predicate_verb","surface":"makes"},{"start":11,"end":17,"role":"direct_object","surface":"sense."}]'::jsonb, '[{"surface":"That","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"makes","pos":"verb","ipa":"/meɪks/","gloss":"faz"},{"surface":"sense","pos":"noun","ipa":"/sɛns/","gloss":"sentido"}]'::jsonb),
  ('unit-street-a1-03-08', 'lesson-street-a1-03', 8, 'sentence', 'Good for you!', 'Que bom pra você!', '/ɡʊd fɔːr juː/', 'Parabenizar alguém.', '[{"start":0,"end":4,"role":"predicate_adj","surface":"Good"},{"start":5,"end":13,"role":"adverbial","surface":"for you!"}]'::jsonb, '[{"surface":"Good","pos":"adjective","ipa":"/ɡʊd/","gloss":"bom"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"}]'::jsonb),
  ('unit-street-a1-03-09', 'lesson-street-a1-03', 9, 'sentence', 'Seriously? That sucks.', 'Sério? Que droga.', '/ˈsɪriəsli ðæt sʌks/', '"That sucks" = que chato, que droga (informal).', '[{"start":0,"end":10,"role":"discourse_marker","surface":"Seriously?"},{"start":11,"end":15,"role":"subject","surface":"That"},{"start":16,"end":22,"role":"predicate_verb","surface":"sucks."}]'::jsonb, '[{"surface":"Seriously","pos":"adverb","ipa":"/ˈsɪriəsli/","gloss":"sério?"},{"surface":"That","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"sucks","pos":"verb","ipa":"/sʌks/","gloss":"é uma droga (gíria)"}]'::jsonb),
  ('unit-street-a1-03-10', 'lesson-street-a1-03', 10, 'sentence', 'Whatever you want.', 'O que você quiser.', '/wʌtˈɛvər juː wɑːnt/', 'Deixar a escolha para o outro.', '[{"start":0,"end":8,"role":"direct_object","surface":"Whatever"},{"start":9,"end":12,"role":"subject","surface":"you"},{"start":13,"end":18,"role":"predicate_verb","surface":"want."}]'::jsonb, '[{"surface":"Whatever","pos":"pronoun","ipa":"/wʌtˈɛvər/","gloss":"o que (quer que seja)"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"want","pos":"verb","ipa":"/wɑːnt/","gloss":"querer"}]'::jsonb)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations)
VALUES
  ('unit-street-a1-04-01', 'lesson-street-a1-04', 1, 'sentence', 'Can you do me a favor?', 'Pode me fazer um favor?', '/kæn juː duː miː ə ˈfeɪvər/', 'Em inglês é "do a favor", não "make".', '[{"start":0,"end":3,"role":"predicate_verb","surface":"Can"},{"start":4,"end":7,"role":"subject","surface":"you"},{"start":8,"end":13,"role":"predicate_verb","surface":"do me"},{"start":14,"end":22,"role":"direct_object","surface":"a favor?"}]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"favor","pos":"noun","ipa":"/ˈfeɪvər/","gloss":"favor"}]'::jsonb),
  ('unit-street-a1-04-02', 'lesson-street-a1-04', 2, 'sentence', 'Could you give me a hand?', 'Você pode me dar uma mão?', '/kʊd juː ɡɪv miː ə hænd/', '"Give a hand" = ajudar.', '[{"start":0,"end":5,"role":"predicate_verb","surface":"Could"},{"start":6,"end":9,"role":"subject","surface":"you"},{"start":10,"end":17,"role":"predicate_verb","surface":"give me"},{"start":18,"end":25,"role":"direct_object","surface":"a hand?"}]'::jsonb, '[{"surface":"Could","pos":"auxiliary verb","ipa":"/kʊd/","gloss":"poderia"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"give","pos":"verb","ipa":"/ɡɪv/","gloss":"dar"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"hand","pos":"noun","ipa":"/hænd/","gloss":"mão, ajuda"}]'::jsonb),
  ('unit-street-a1-04-03', 'lesson-street-a1-04', 3, 'sentence', 'Do you mind if I sit here?', 'Você se importa se eu sentar aqui?', '/duː juː maɪnd ɪf aɪ sɪt hɪr/', 'Resposta "no" = pode sentar.', '[{"start":0,"end":2,"role":"predicate_verb","surface":"Do"},{"start":3,"end":6,"role":"subject","surface":"you"},{"start":7,"end":11,"role":"predicate_verb","surface":"mind"},{"start":12,"end":26,"role":"adverbial","surface":"if I sit here?"}]'::jsonb, '[{"surface":"Do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"mind","pos":"verb","ipa":"/maɪnd/","gloss":"se importar"},{"surface":"if","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"sit","pos":"verb","ipa":"/sɪt/","gloss":"sentar"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"}]'::jsonb),
  ('unit-street-a1-04-04', 'lesson-street-a1-04', 4, 'sentence', 'Thanks a lot, I owe you one.', 'Valeu mesmo, te devo uma.', '/θæŋks ə lɑːt aɪ oʊ juː wʌn/', '"I owe you one" = fico te devendo.', '[{"start":0,"end":13,"role":"discourse_marker","surface":"Thanks a lot,"},{"start":14,"end":15,"role":"subject","surface":"I"},{"start":16,"end":23,"role":"predicate_verb","surface":"owe you"},{"start":24,"end":28,"role":"direct_object","surface":"one."}]'::jsonb, '[{"surface":"Thanks","pos":"interjection","ipa":"/θæŋks/","gloss":"obrigado, valeu"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"lot","pos":"noun","ipa":"/lɑːt/","gloss":"muito (a lot)"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"owe","pos":"verb","ipa":"/oʊ/","gloss":"dever"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"one","pos":"pronoun","ipa":"/wʌn/","gloss":"uma (I owe you one)"}]'::jsonb),
  ('unit-street-a1-04-05', 'lesson-street-a1-04', 5, 'sentence', 'No problem, anytime.', 'De boa, quando precisar.', '/noʊ ˈprɑːbləm ˈɛnitaɪm/', 'Resposta comum a "thanks".', '[{"start":0,"end":11,"role":"discourse_marker","surface":"No problem,"},{"start":12,"end":20,"role":"adverbial","surface":"anytime."}]'::jsonb, '[{"surface":"No","pos":"determiner","ipa":"/noʊ/","gloss":"nenhum; não"},{"surface":"problem","pos":"noun","ipa":"/ˈprɑːbləm/","gloss":"problema"},{"surface":"anytime","pos":"adverb","ipa":"/ˈɛnitaɪm/","gloss":"quando quiser"}]'::jsonb),
  ('unit-street-a1-04-06', 'lesson-street-a1-04', 6, 'sentence', 'Don''t worry about it.', 'Não esquenta com isso.', '/doʊnt ˈwɜːri əˈbaʊt ɪt/', 'Tranquilizar alguém.', '[{"start":0,"end":11,"role":"predicate_verb","surface":"Don''t worry"},{"start":12,"end":21,"role":"adverbial","surface":"about it."}]'::jsonb, '[{"surface":"Don''t","pos":"auxiliary verb","ipa":"/doʊnt/","gloss":"não"},{"surface":"worry","pos":"verb","ipa":"/ˈwɜːri/","gloss":"se preocupar"},{"surface":"about","pos":"preposition","ipa":"/əˈbaʊt/","gloss":"sobre"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"}]'::jsonb),
  ('unit-street-a1-04-07', 'lesson-street-a1-04', 7, 'sentence', 'Can I borrow your charger?', 'Posso pegar seu carregador emprestado?', '/kæn aɪ ˈbɑːroʊ jʊr ˈtʃɑːrdʒər/', '"Borrow" = pegar emprestado; "lend" = emprestar.', '[{"start":0,"end":3,"role":"predicate_verb","surface":"Can"},{"start":4,"end":5,"role":"subject","surface":"I"},{"start":6,"end":12,"role":"predicate_verb","surface":"borrow"},{"start":13,"end":26,"role":"direct_object","surface":"your charger?"}]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"borrow","pos":"verb","ipa":"/ˈbɑːroʊ/","gloss":"pegar emprestado"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"charger","pos":"noun","ipa":"/ˈtʃɑːrdʒər/","gloss":"carregador"}]'::jsonb),
  ('unit-street-a1-04-08', 'lesson-street-a1-04', 8, 'sentence', 'Sorry to bother you.', 'Desculpa incomodar.', '/ˈsɑːri tuː ˈbɑːðər juː/', 'Abrir um pedido com educação.', '[{"start":0,"end":5,"role":"discourse_marker","surface":"Sorry"},{"start":6,"end":20,"role":"predicate_verb","surface":"to bother you."}]'::jsonb, '[{"surface":"Sorry","pos":"adjective","ipa":"/ˈsɑːri/","gloss":"desculpa"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"bother","pos":"verb","ipa":"/ˈbɑːðər/","gloss":"incomodar"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"}]'::jsonb),
  ('unit-street-a1-04-09', 'lesson-street-a1-04', 9, 'sentence', 'I really appreciate it.', 'Agradeço muito.', '/aɪ ˈriːəli əˈpriːʃieɪt ɪt/', 'Agradecimento mais caloroso que "thanks".', '[{"start":0,"end":1,"role":"subject","surface":"I"},{"start":2,"end":19,"role":"predicate_verb","surface":"really appreciate"},{"start":20,"end":23,"role":"direct_object","surface":"it."}]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"really","pos":"adverb","ipa":"/ˈriːəli/","gloss":"muito, de verdade"},{"surface":"appreciate","pos":"verb","ipa":"/əˈpriːʃieɪt/","gloss":"agradecer, valorizar"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"}]'::jsonb),
  ('unit-street-a1-04-10', 'lesson-street-a1-04', 10, 'sentence', 'You''re a lifesaver!', 'Você salvou minha vida!', '/jʊr ə ˈlaɪfseɪvər/', 'Exagero carinhoso para agradecer.', '[{"start":0,"end":6,"role":"subject","surface":"You''re"},{"start":7,"end":19,"role":"predicate_adj","surface":"a lifesaver!"}]'::jsonb, '[{"surface":"You''re","pos":"pronoun","ipa":"/jʊr/","gloss":"você está, você é"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"lifesaver","pos":"noun","ipa":"/ˈlaɪfseɪvər/","gloss":"salva-vidas"}]'::jsonb)
INSERT INTO public.course_catalog (id, slug, title, short_description, long_description, level, category, order_index, is_published)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations)
VALUES
  ('unit-travel-a2-01-01', 'lesson-travel-a2-01', 1, 'sentence', 'I''d like to check in, please.', 'Eu queria fazer o check-in, por favor.', '/aɪd laɪk tuː tʃɛk ɪn pliːz/', '"I''d like" = eu gostaria; mais educado que "I want".', '[{"start":0,"end":8,"role":"predicate_verb","surface":"I''d like"},{"start":9,"end":21,"role":"direct_object","surface":"to check in,"},{"start":22,"end":29,"role":"discourse_marker","surface":"please."}]'::jsonb, '[{"surface":"I''d","pos":"pronoun","ipa":"/aɪd/","gloss":"eu (gostaria)"},{"surface":"like","pos":"verb","ipa":"/laɪk/","gloss":"gostar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"check","pos":"verb","ipa":"/tʃɛk/","gloss":"fazer (check-in)"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"please","pos":"adverb","ipa":"/pliːz/","gloss":"por favor"}]'::jsonb),
  ('unit-travel-a2-01-02', 'lesson-travel-a2-01', 2, 'sentence', 'Can I have a window seat?', 'Pode me dar um assento na janela?', '/kæn aɪ hæv ə ˈwɪndoʊ siːt/', '"Aisle seat" = corredor.', '[{"start":0,"end":3,"role":"predicate_verb","surface":"Can"},{"start":4,"end":5,"role":"subject","surface":"I"},{"start":6,"end":10,"role":"predicate_verb","surface":"have"},{"start":11,"end":25,"role":"direct_object","surface":"a window seat?"}]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"window","pos":"noun","ipa":"/ˈwɪndoʊ/","gloss":"janela"},{"surface":"seat","pos":"noun","ipa":"/siːt/","gloss":"assento"}]'::jsonb),
  ('unit-travel-a2-01-03', 'lesson-travel-a2-01', 3, 'sentence', 'How many bags are you checking?', 'Quantas malas você vai despachar?', '/haʊ ˈmɛni bæɡz ɑːr juː ˈtʃɛkɪŋ/', '"Check a bag" = despachar mala.', '[{"start":0,"end":13,"role":"direct_object","surface":"How many bags"},{"start":14,"end":17,"role":"predicate_verb","surface":"are"},{"start":18,"end":21,"role":"subject","surface":"you"},{"start":22,"end":31,"role":"predicate_verb","surface":"checking?"}]'::jsonb, '[{"surface":"How","pos":"adverb","ipa":"/haʊ/","gloss":"como"},{"surface":"many","pos":"determiner","ipa":"/ˈmɛni/","gloss":"muitos (how many)"},{"surface":"bags","pos":"noun","ipa":"/bæɡz/","gloss":"malas"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"checking","pos":"verb","ipa":"/ˈtʃɛkɪŋ/","gloss":"despachando"}]'::jsonb),
  ('unit-travel-a2-01-04', 'lesson-travel-a2-01', 4, 'sentence', 'Just this carry-on.', 'Só essa mala de mão.', '/dʒʌst ðɪs ˈkæri ɑːn/', '"Carry-on" = bagagem de mão.', '[{"start":0,"end":4,"role":"adverbial","surface":"Just"},{"start":5,"end":19,"role":"direct_object","surface":"this carry-on."}]'::jsonb, '[{"surface":"Just","pos":"adverb","ipa":"/dʒʌst/","gloss":"só, apenas"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"carry-on","pos":"noun","ipa":"/ˈkæri ɑːn/","gloss":"bagagem de mão"}]'::jsonb),
  ('unit-travel-a2-01-05', 'lesson-travel-a2-01', 5, 'sentence', 'Which gate is it?', 'Qual é o portão?', '/wɪtʃ ɡeɪt ɪz ɪt/', 'Pergunta curta no balcão.', '[{"start":0,"end":10,"role":"predicate_adj","surface":"Which gate"},{"start":11,"end":13,"role":"predicate_verb","surface":"is"},{"start":14,"end":17,"role":"subject","surface":"it?"}]'::jsonb, '[{"surface":"Which","pos":"determiner","ipa":"/wɪtʃ/","gloss":"qual"},{"surface":"gate","pos":"noun","ipa":"/ɡeɪt/","gloss":"portão"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"}]'::jsonb),
  ('unit-travel-a2-01-06', 'lesson-travel-a2-01', 6, 'sentence', 'The flight is delayed an hour.', 'O voo está atrasado uma hora.', '/ðə flaɪt ɪz dɪˈleɪd ən ˈaʊər/', '"Delayed" = atrasado; "canceled" = cancelado.', '[{"start":0,"end":10,"role":"subject","surface":"The flight"},{"start":11,"end":21,"role":"predicate_verb","surface":"is delayed"},{"start":22,"end":30,"role":"adverbial","surface":"an hour."}]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"flight","pos":"noun","ipa":"/flaɪt/","gloss":"voo"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"delayed","pos":"adjective","ipa":"/dɪˈleɪd/","gloss":"atrasado"},{"surface":"an","pos":"determiner","ipa":"/ən/","gloss":"um, uma"},{"surface":"hour","pos":"noun","ipa":"/ˈaʊər/","gloss":"hora"}]'::jsonb),
  ('unit-travel-a2-01-07', 'lesson-travel-a2-01', 7, 'sentence', 'Boarding starts in twenty minutes.', 'O embarque começa em vinte minutos.', '/ˈbɔːrdɪŋ stɑːrts ɪn ˈtwɛnti ˈmɪnɪts/', 'Aviso comum no portão.', '[{"start":0,"end":8,"role":"subject","surface":"Boarding"},{"start":9,"end":15,"role":"predicate_verb","surface":"starts"},{"start":16,"end":34,"role":"adverbial","surface":"in twenty minutes."}]'::jsonb, '[{"surface":"Boarding","pos":"noun","ipa":"/ˈbɔːrdɪŋ/","gloss":"embarque"},{"surface":"starts","pos":"verb","ipa":"/stɑːrts/","gloss":"começa"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"twenty","pos":"numeral","ipa":"/ˈtwɛnti/","gloss":"vinte"},{"surface":"minutes","pos":"noun","ipa":"/ˈmɪnɪts/","gloss":"minutos"}]'::jsonb),
  ('unit-travel-a2-01-08', 'lesson-travel-a2-01', 8, 'sentence', 'I missed my connection.', 'Perdi minha conexão.', '/aɪ mɪst maɪ kəˈnɛkʃən/', '"Connection" = voo de conexão.', '[{"start":0,"end":1,"role":"subject","surface":"I"},{"start":2,"end":8,"role":"predicate_verb","surface":"missed"},{"start":9,"end":23,"role":"direct_object","surface":"my connection."}]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"missed","pos":"verb","ipa":"/mɪst/","gloss":"perdi"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"connection","pos":"noun","ipa":"/kəˈnɛkʃən/","gloss":"conexão"}]'::jsonb),
  ('unit-travel-a2-01-09', 'lesson-travel-a2-01', 9, 'sentence', 'My bag didn''t show up.', 'Minha mala não apareceu.', '/maɪ bæɡ ˈdɪdənt ʃoʊ ʌp/', '"Show up" = aparecer.', '[{"start":0,"end":6,"role":"subject","surface":"My bag"},{"start":7,"end":22,"role":"predicate_verb","surface":"didn''t show up."}]'::jsonb, '[{"surface":"My","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"bag","pos":"noun","ipa":"/bæɡ/","gloss":"mala, bolsa"},{"surface":"didn''t","pos":"auxiliary verb","ipa":"/ˈdɪdənt/","gloss":"não (passado)"},{"surface":"show","pos":"verb","ipa":"/ʃoʊ/","gloss":"aparecer (show up)"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"}]'::jsonb),
  ('unit-travel-a2-01-10', 'lesson-travel-a2-01', 10, 'sentence', 'Where do I pick up my luggage?', 'Onde eu pego minha bagagem?', '/wɛr duː aɪ pɪk ʌp maɪ ˈlʌɡɪdʒ/', '"Luggage" não tem plural.', '[{"start":0,"end":5,"role":"adverbial","surface":"Where"},{"start":6,"end":8,"role":"predicate_verb","surface":"do"},{"start":9,"end":10,"role":"subject","surface":"I"},{"start":11,"end":18,"role":"predicate_verb","surface":"pick up"},{"start":19,"end":30,"role":"direct_object","surface":"my luggage?"}]'::jsonb, '[{"surface":"Where","pos":"adverb","ipa":"/wɛr/","gloss":"onde"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"pick","pos":"verb","ipa":"/pɪk/","gloss":"pegar (pick up)"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"luggage","pos":"noun","ipa":"/ˈlʌɡɪdʒ/","gloss":"bagagem"}]'::jsonb)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations)
VALUES
  ('unit-travel-a2-02-01', 'lesson-travel-a2-02', 1, 'sentence', 'I have a reservation under Silva.', 'Tenho uma reserva no nome de Silva.', '/aɪ hæv ə ˌrɛzərˈveɪʃən ˈʌndər ˈsɪlvə/', '"Under" + nome = no nome de.', '[{"start":0,"end":1,"role":"subject","surface":"I"},{"start":2,"end":6,"role":"predicate_verb","surface":"have"},{"start":7,"end":20,"role":"direct_object","surface":"a reservation"},{"start":21,"end":33,"role":"adverbial","surface":"under Silva."}]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"reservation","pos":"noun","ipa":"/ˌrɛzərˈveɪʃən/","gloss":"reserva"},{"surface":"under","pos":"preposition","ipa":"/ˈʌndər/","gloss":"no nome de, sob"},{"surface":"Silva","pos":"proper noun","ipa":"/ˈsɪlvə/","gloss":"Silva (sobrenome)"}]'::jsonb),
  ('unit-travel-a2-02-02', 'lesson-travel-a2-02', 2, 'sentence', 'Is breakfast included?', 'O café da manhã está incluso?', '/ɪz ˈbrɛkfəst ɪnˈkluːdɪd/', 'Pergunta essencial no check-in.', '[{"start":0,"end":2,"role":"predicate_verb","surface":"Is"},{"start":3,"end":12,"role":"subject","surface":"breakfast"},{"start":13,"end":22,"role":"predicate_adj","surface":"included?"}]'::jsonb, '[{"surface":"Is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"breakfast","pos":"noun","ipa":"/ˈbrɛkfəst/","gloss":"café da manhã"},{"surface":"included","pos":"adjective","ipa":"/ɪnˈkluːdɪd/","gloss":"incluído"}]'::jsonb),
  ('unit-travel-a2-02-03', 'lesson-travel-a2-02', 3, 'sentence', 'What time is checkout?', 'Que horas é o checkout?', '/wʌt taɪm ɪz ˈtʃɛkaʊt/', 'Horário de saída do quarto.', '[{"start":0,"end":9,"role":"adverbial","surface":"What time"},{"start":10,"end":12,"role":"predicate_verb","surface":"is"},{"start":13,"end":22,"role":"subject","surface":"checkout?"}]'::jsonb, '[{"surface":"What","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"checkout","pos":"noun","ipa":"/ˈtʃɛkaʊt/","gloss":"saída do hotel"}]'::jsonb),
  ('unit-travel-a2-02-04', 'lesson-travel-a2-02', 4, 'sentence', 'The air conditioning isn''t working.', 'O ar-condicionado não está funcionando.', '/ðə ɛr kənˈdɪʃənɪŋ ˈɪzənt ˈwɜːrkɪŋ/', '"Working" = funcionando (máquinas).', '[{"start":0,"end":20,"role":"subject","surface":"The air conditioning"},{"start":21,"end":35,"role":"predicate_verb","surface":"isn''t working."}]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"air","pos":"noun","ipa":"/ɛr/","gloss":"ar"},{"surface":"conditioning","pos":"noun","ipa":"/kənˈdɪʃənɪŋ/","gloss":"condicionamento (ar-condicionado)"},{"surface":"isn''t","pos":"auxiliary verb","ipa":"/ˈɪzənt/","gloss":"não é, não está"},{"surface":"working","pos":"verb","ipa":"/ˈwɜːrkɪŋ/","gloss":"funcionando; trabalhando"}]'::jsonb),
  ('unit-travel-a2-02-05', 'lesson-travel-a2-02', 5, 'sentence', 'Could I get some extra towels?', 'Poderia me trazer mais toalhas?', '/kʊd aɪ ɡɛt sʌm ˈɛkstrə ˈtaʊəlz/', '"Get" = conseguir/receber.', '[{"start":0,"end":5,"role":"predicate_verb","surface":"Could"},{"start":6,"end":7,"role":"subject","surface":"I"},{"start":8,"end":11,"role":"predicate_verb","surface":"get"},{"start":12,"end":30,"role":"direct_object","surface":"some extra towels?"}]'::jsonb, '[{"surface":"Could","pos":"auxiliary verb","ipa":"/kʊd/","gloss":"poderia"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"get","pos":"verb","ipa":"/ɡɛt/","gloss":"conseguir, chegar"},{"surface":"some","pos":"determiner","ipa":"/sʌm/","gloss":"algumas"},{"surface":"extra","pos":"adjective","ipa":"/ˈɛkstrə/","gloss":"a mais, extra"},{"surface":"towels","pos":"noun","ipa":"/ˈtaʊəlz/","gloss":"toalhas"}]'::jsonb),
  ('unit-travel-a2-02-06', 'lesson-travel-a2-02', 6, 'sentence', 'What''s the Wi-Fi password?', 'Qual é a senha do Wi-Fi?', '/wʌts ðə ˈwaɪ faɪ ˈpæswɜːrd/', 'A pergunta mais feita em qualquer hotel.', '[{"start":0,"end":6,"role":"predicate_verb","surface":"What''s"},{"start":7,"end":26,"role":"subject","surface":"the Wi-Fi password?"}]'::jsonb, '[{"surface":"What''s","pos":"pronoun","ipa":"/wʌts/","gloss":"qual é"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"Wi-Fi","pos":"noun","ipa":"/ˈwaɪ faɪ/","gloss":"Wi-Fi"},{"surface":"password","pos":"noun","ipa":"/ˈpæswɜːrd/","gloss":"senha"}]'::jsonb),
  ('unit-travel-a2-02-07', 'lesson-travel-a2-02', 7, 'sentence', 'Can I leave my bags here?', 'Posso deixar minhas malas aqui?', '/kæn aɪ liːv maɪ bæɡz hɪr/', 'Útil antes do check-in ou depois do checkout.', '[{"start":0,"end":3,"role":"predicate_verb","surface":"Can"},{"start":4,"end":5,"role":"subject","surface":"I"},{"start":6,"end":11,"role":"predicate_verb","surface":"leave"},{"start":12,"end":19,"role":"direct_object","surface":"my bags"},{"start":20,"end":25,"role":"adverbial","surface":"here?"}]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"leave","pos":"verb","ipa":"/liːv/","gloss":"deixar"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"bags","pos":"noun","ipa":"/bæɡz/","gloss":"malas"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"}]'::jsonb),
  ('unit-travel-a2-02-08', 'lesson-travel-a2-02', 8, 'sentence', 'The room is too noisy.', 'O quarto é barulhento demais.', '/ðə ruːm ɪz tuː ˈnɔɪzi/', '"Too" = demais (negativo).', '[{"start":0,"end":8,"role":"subject","surface":"The room"},{"start":9,"end":11,"role":"predicate_verb","surface":"is"},{"start":12,"end":22,"role":"predicate_adj","surface":"too noisy."}]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"room","pos":"noun","ipa":"/ruːm/","gloss":"quarto"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"too","pos":"adverb","ipa":"/tuː/","gloss":"demais"},{"surface":"noisy","pos":"adjective","ipa":"/ˈnɔɪzi/","gloss":"barulhento"}]'::jsonb),
  ('unit-travel-a2-02-09', 'lesson-travel-a2-02', 9, 'sentence', 'I''d like to change rooms.', 'Eu queria trocar de quarto.', '/aɪd laɪk tuː tʃeɪndʒ ruːmz/', 'Em inglês: "change rooms" no plural.', '[{"start":0,"end":8,"role":"predicate_verb","surface":"I''d like"},{"start":9,"end":25,"role":"direct_object","surface":"to change rooms."}]'::jsonb, '[{"surface":"I''d","pos":"pronoun","ipa":"/aɪd/","gloss":"eu (gostaria)"},{"surface":"like","pos":"verb","ipa":"/laɪk/","gloss":"gostar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"change","pos":"verb","ipa":"/tʃeɪndʒ/","gloss":"trocar"},{"surface":"rooms","pos":"noun","ipa":"/ruːmz/","gloss":"quartos"}]'::jsonb),
  ('unit-travel-a2-02-10', 'lesson-travel-a2-02', 10, 'sentence', 'Thanks, everything was great.', 'Obrigado, estava tudo ótimo.', '/θæŋks ˈɛvriθɪŋ wɑːz ɡreɪt/', 'Despedida no checkout.', '[{"start":0,"end":7,"role":"discourse_marker","surface":"Thanks,"},{"start":8,"end":18,"role":"subject","surface":"everything"},{"start":19,"end":22,"role":"predicate_verb","surface":"was"},{"start":23,"end":29,"role":"predicate_adj","surface":"great."}]'::jsonb, '[{"surface":"Thanks","pos":"interjection","ipa":"/θæŋks/","gloss":"obrigado, valeu"},{"surface":"everything","pos":"pronoun","ipa":"/ˈɛvriθɪŋ/","gloss":"tudo"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"great","pos":"adjective","ipa":"/ɡreɪt/","gloss":"ótimo"}]'::jsonb)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations)
VALUES
  ('unit-travel-a2-03-01', 'lesson-travel-a2-03', 1, 'sentence', 'How do I get to the station?', 'Como eu chego na estação?', '/haʊ duː aɪ ɡɛt tuː ðə ˈsteɪʃən/', '"Get to" = chegar a um lugar.', '[{"start":0,"end":3,"role":"adverbial","surface":"How"},{"start":4,"end":6,"role":"predicate_verb","surface":"do"},{"start":7,"end":8,"role":"subject","surface":"I"},{"start":9,"end":12,"role":"predicate_verb","surface":"get"},{"start":13,"end":28,"role":"adverbial","surface":"to the station?"}]'::jsonb, '[{"surface":"How","pos":"adverb","ipa":"/haʊ/","gloss":"como"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"get","pos":"verb","ipa":"/ɡɛt/","gloss":"conseguir, chegar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"station","pos":"noun","ipa":"/ˈsteɪʃən/","gloss":"estação"}]'::jsonb),
  ('unit-travel-a2-03-02', 'lesson-travel-a2-03', 2, 'sentence', 'Is it within walking distance?', 'Dá pra ir a pé?', '/ɪz ɪt wɪˈðɪn ˈwɔːkɪŋ ˈdɪstəns/', 'Literalmente: está a uma distância de caminhada?', '[{"start":0,"end":2,"role":"predicate_verb","surface":"Is"},{"start":3,"end":5,"role":"subject","surface":"it"},{"start":6,"end":30,"role":"predicate_adj","surface":"within walking distance?"}]'::jsonb, '[{"surface":"Is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"within","pos":"preposition","ipa":"/wɪˈðɪn/","gloss":"dentro de"},{"surface":"walking","pos":"noun","ipa":"/ˈwɔːkɪŋ/","gloss":"caminhada"},{"surface":"distance","pos":"noun","ipa":"/ˈdɪstəns/","gloss":"distância"}]'::jsonb),
  ('unit-travel-a2-03-03', 'lesson-travel-a2-03', 3, 'sentence', 'Which line goes downtown?', 'Qual linha vai pro centro?', '/wɪtʃ laɪn ɡoʊz ˌdaʊnˈtaʊn/', '"Downtown" = centro da cidade.', '[{"start":0,"end":10,"role":"subject","surface":"Which line"},{"start":11,"end":15,"role":"predicate_verb","surface":"goes"},{"start":16,"end":25,"role":"adverbial","surface":"downtown?"}]'::jsonb, '[{"surface":"Which","pos":"determiner","ipa":"/wɪtʃ/","gloss":"qual"},{"surface":"line","pos":"noun","ipa":"/laɪn/","gloss":"linha"},{"surface":"goes","pos":"verb","ipa":"/ɡoʊz/","gloss":"vai"},{"surface":"downtown","pos":"adverb","ipa":"/ˌdaʊnˈtaʊn/","gloss":"para o centro"}]'::jsonb),
  ('unit-travel-a2-03-04', 'lesson-travel-a2-03', 4, 'sentence', 'A one-way ticket, please.', 'Uma passagem só de ida, por favor.', '/ə ˌwʌn ˈweɪ ˈtɪkɪt pliːz/', '"Round-trip" = ida e volta.', '[{"start":0,"end":17,"role":"direct_object","surface":"A one-way ticket,"},{"start":18,"end":25,"role":"discourse_marker","surface":"please."}]'::jsonb, '[{"surface":"A","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"one-way","pos":"adjective","ipa":"/ˌwʌn ˈweɪ/","gloss":"só de ida"},{"surface":"ticket","pos":"noun","ipa":"/ˈtɪkɪt/","gloss":"passagem, bilhete"},{"surface":"please","pos":"adverb","ipa":"/pliːz/","gloss":"por favor"}]'::jsonb),
  ('unit-travel-a2-03-05', 'lesson-travel-a2-03', 5, 'sentence', 'Does this bus stop near the museum?', 'Esse ônibus para perto do museu?', '/dʌz ðɪs bʌs stɑːp nɪr ðə mjuˈziːəm/', '"Stop" também é verbo.', '[{"start":0,"end":4,"role":"predicate_verb","surface":"Does"},{"start":5,"end":13,"role":"subject","surface":"this bus"},{"start":14,"end":18,"role":"predicate_verb","surface":"stop"},{"start":19,"end":35,"role":"adverbial","surface":"near the museum?"}]'::jsonb, '[{"surface":"Does","pos":"auxiliary verb","ipa":"/dʌz/","gloss":"auxiliar de pergunta (3ª pessoa)"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"bus","pos":"noun","ipa":"/bʌs/","gloss":"ônibus"},{"surface":"stop","pos":"verb","ipa":"/stɑːp/","gloss":"parar"},{"surface":"near","pos":"preposition","ipa":"/nɪr/","gloss":"perto de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"museum","pos":"noun","ipa":"/mjuˈziːəm/","gloss":"museu"}]'::jsonb),
  ('unit-travel-a2-03-06', 'lesson-travel-a2-03', 6, 'sentence', 'You can drop me off here.', 'Pode me deixar aqui.', '/juː kæn drɑːp miː ɔːf hɪr/', '"Drop off" = deixar alguém num lugar.', '[{"start":0,"end":3,"role":"subject","surface":"You"},{"start":4,"end":12,"role":"predicate_verb","surface":"can drop"},{"start":13,"end":15,"role":"direct_object","surface":"me"},{"start":16,"end":25,"role":"adverbial","surface":"off here."}]'::jsonb, '[{"surface":"You","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"drop","pos":"verb","ipa":"/drɑːp/","gloss":"deixar (drop off)"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"off","pos":"particle","ipa":"/ɔːf/","gloss":"(partícula: off)"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"}]'::jsonb),
  ('unit-travel-a2-03-07', 'lesson-travel-a2-03', 7, 'sentence', 'How much is the fare?', 'Quanto é a tarifa?', '/haʊ mʌtʃ ɪz ðə fɛr/', '"Fare" = preço da passagem ou corrida.', '[{"start":0,"end":8,"role":"predicate_adj","surface":"How much"},{"start":9,"end":11,"role":"predicate_verb","surface":"is"},{"start":12,"end":21,"role":"subject","surface":"the fare?"}]'::jsonb, '[{"surface":"How","pos":"adverb","ipa":"/haʊ/","gloss":"como"},{"surface":"much","pos":"adverb","ipa":"/mʌtʃ/","gloss":"quanto (how much)"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"fare","pos":"noun","ipa":"/fɛr/","gloss":"tarifa"}]'::jsonb),
  ('unit-travel-a2-03-08', 'lesson-travel-a2-03', 8, 'sentence', 'I think we''re going the wrong way.', 'Acho que a gente tá indo pro lado errado.', '/aɪ θɪŋk wɪr ˈɡoʊɪŋ ðə rɔːŋ weɪ/', 'Avisar o motorista com educação.', '[{"start":0,"end":1,"role":"subject","surface":"I"},{"start":2,"end":7,"role":"predicate_verb","surface":"think"},{"start":8,"end":19,"role":"predicate_verb","surface":"we''re going"},{"start":20,"end":34,"role":"adverbial","surface":"the wrong way."}]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"think","pos":"verb","ipa":"/θɪŋk/","gloss":"achar, pensar"},{"surface":"we''re","pos":"pronoun","ipa":"/wɪr/","gloss":"nós estamos"},{"surface":"going","pos":"verb","ipa":"/ˈɡoʊɪŋ/","gloss":"indo"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"wrong","pos":"adjective","ipa":"/rɔːŋ/","gloss":"errado"},{"surface":"way","pos":"noun","ipa":"/weɪ/","gloss":"caminho; jeito"}]'::jsonb),
  ('unit-travel-a2-03-09', 'lesson-travel-a2-03', 9, 'sentence', 'My ride is almost here.', 'Meu carro está quase chegando.', '/maɪ raɪd ɪz ˈɔːlmoʊst hɪr/', '"Ride" = carona ou carro de aplicativo.', '[{"start":0,"end":7,"role":"subject","surface":"My ride"},{"start":8,"end":10,"role":"predicate_verb","surface":"is"},{"start":11,"end":23,"role":"adverbial","surface":"almost here."}]'::jsonb, '[{"surface":"My","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"ride","pos":"noun","ipa":"/raɪd/","gloss":"carona, corrida"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"almost","pos":"adverb","ipa":"/ˈɔːlmoʊst/","gloss":"quase"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"}]'::jsonb),
  ('unit-travel-a2-03-10', 'lesson-travel-a2-03', 10, 'sentence', 'Could you turn on the AC?', 'Pode ligar o ar?', '/kʊd juː tɜːrn ɑːn ðə ˌeɪˈsiː/', '"AC" = ar-condicionado.', '[{"start":0,"end":5,"role":"predicate_verb","surface":"Could"},{"start":6,"end":9,"role":"subject","surface":"you"},{"start":10,"end":17,"role":"predicate_verb","surface":"turn on"},{"start":18,"end":25,"role":"direct_object","surface":"the AC?"}]'::jsonb, '[{"surface":"Could","pos":"auxiliary verb","ipa":"/kʊd/","gloss":"poderia"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"turn","pos":"verb","ipa":"/tɜːrn/","gloss":"ligar (turn on)"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"AC","pos":"noun","ipa":"/ˌeɪˈsiː/","gloss":"ar-condicionado"}]'::jsonb)
INSERT INTO public.course_catalog (id, slug, title, short_description, long_description, level, category, order_index, is_published)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations)
VALUES
  ('unit-work-b1-01-01', 'lesson-work-b1-01', 1, 'sentence', 'Let''s get started.', 'Vamos começar.', '/lɛts ɡɛt ˈstɑːrtɪd/', 'Abertura padrão de reunião.', '[{"start":0,"end":18,"role":"predicate_verb","surface":"Let''s get started."}]'::jsonb, '[{"surface":"Let''s","pos":"verb","ipa":"/lɛts/","gloss":"vamos"},{"surface":"get","pos":"verb","ipa":"/ɡɛt/","gloss":"conseguir, chegar"},{"surface":"started","pos":"verb","ipa":"/ˈstɑːrtɪd/","gloss":"começado"}]'::jsonb),
  ('unit-work-b1-01-02', 'lesson-work-b1-01', 2, 'sentence', 'Can everyone hear me?', 'Todo mundo está me ouvindo?', '/kæn ˈɛvriwʌn hɪr miː/', 'Clássico de chamada de vídeo.', '[{"start":0,"end":3,"role":"predicate_verb","surface":"Can"},{"start":4,"end":12,"role":"subject","surface":"everyone"},{"start":13,"end":21,"role":"predicate_verb","surface":"hear me?"}]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"everyone","pos":"pronoun","ipa":"/ˈɛvriwʌn/","gloss":"todo mundo, pessoal"},{"surface":"hear","pos":"verb","ipa":"/hɪr/","gloss":"ouvir"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"}]'::jsonb),
  ('unit-work-b1-01-03', 'lesson-work-b1-01', 3, 'sentence', 'You''re on mute.', 'Você está no mudo.', '/jʊr ɑːn mjuːt/', 'Frase mais dita em reuniões online.', '[{"start":0,"end":6,"role":"subject","surface":"You''re"},{"start":7,"end":15,"role":"predicate_adj","surface":"on mute."}]'::jsonb, '[{"surface":"You''re","pos":"pronoun","ipa":"/jʊr/","gloss":"você está, você é"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"mute","pos":"noun","ipa":"/mjuːt/","gloss":"mudo"}]'::jsonb),
  ('unit-work-b1-01-04', 'lesson-work-b1-01', 4, 'sentence', 'Let''s circle back to that later.', 'Vamos voltar nesse ponto depois.', '/lɛts ˈsɜːrkəl bæk tuː ðæt ˈleɪtər/', '"Circle back" = retomar um assunto.', '[{"start":0,"end":17,"role":"predicate_verb","surface":"Let''s circle back"},{"start":18,"end":25,"role":"adverbial","surface":"to that"},{"start":26,"end":32,"role":"adverbial","surface":"later."}]'::jsonb, '[{"surface":"Let''s","pos":"verb","ipa":"/lɛts/","gloss":"vamos"},{"surface":"circle","pos":"verb","ipa":"/ˈsɜːrkəl/","gloss":"voltar (circle back)"},{"surface":"back","pos":"adverb","ipa":"/bæk/","gloss":"de volta"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"later","pos":"adverb","ipa":"/ˈleɪtər/","gloss":"mais tarde"}]'::jsonb),
  ('unit-work-b1-01-05', 'lesson-work-b1-01', 5, 'sentence', 'Could you share your screen?', 'Pode compartilhar sua tela?', '/kʊd juː ʃɛr jʊr skriːn/', 'Pedido comum em call.', '[{"start":0,"end":5,"role":"predicate_verb","surface":"Could"},{"start":6,"end":9,"role":"subject","surface":"you"},{"start":10,"end":15,"role":"predicate_verb","surface":"share"},{"start":16,"end":28,"role":"direct_object","surface":"your screen?"}]'::jsonb, '[{"surface":"Could","pos":"auxiliary verb","ipa":"/kʊd/","gloss":"poderia"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"share","pos":"verb","ipa":"/ʃɛr/","gloss":"compartilhar"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"screen","pos":"noun","ipa":"/skriːn/","gloss":"tela"}]'::jsonb),
  ('unit-work-b1-01-06', 'lesson-work-b1-01', 6, 'sentence', 'I''d like to add something.', 'Eu queria acrescentar uma coisa.', '/aɪd laɪk tuː æd ˈsʌmθɪŋ/', 'Pedir a palavra com educação.', '[{"start":0,"end":8,"role":"predicate_verb","surface":"I''d like"},{"start":9,"end":26,"role":"direct_object","surface":"to add something."}]'::jsonb, '[{"surface":"I''d","pos":"pronoun","ipa":"/aɪd/","gloss":"eu (gostaria)"},{"surface":"like","pos":"verb","ipa":"/laɪk/","gloss":"gostar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"add","pos":"verb","ipa":"/æd/","gloss":"acrescentar"},{"surface":"something","pos":"pronoun","ipa":"/ˈsʌmθɪŋ/","gloss":"alguma coisa"}]'::jsonb),
  ('unit-work-b1-01-07', 'lesson-work-b1-01', 7, 'sentence', 'I see your point, but I disagree.', 'Entendo seu ponto, mas discordo.', '/aɪ siː jʊr pɔɪnt bʌt aɪ ˌdɪsəˈɡriː/', 'Discordar reconhecendo o outro lado.', '[{"start":0,"end":1,"role":"subject","surface":"I"},{"start":2,"end":5,"role":"predicate_verb","surface":"see"},{"start":6,"end":17,"role":"direct_object","surface":"your point,"},{"start":18,"end":33,"role":"predicate_verb","surface":"but I disagree."}]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"see","pos":"verb","ipa":"/siː/","gloss":"ver, entender"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"point","pos":"noun","ipa":"/pɔɪnt/","gloss":"ponto, argumento"},{"surface":"but","pos":"conjunction","ipa":"/bʌt/","gloss":"mas"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"disagree","pos":"verb","ipa":"/ˌdɪsəˈɡriː/","gloss":"discordar"}]'::jsonb),
  ('unit-work-b1-01-08', 'lesson-work-b1-01', 8, 'sentence', 'Let''s take this offline.', 'Vamos falar disso fora da reunião.', '/lɛts teɪk ðɪs ˌɔːfˈlaɪn/', '"Take offline" = tratar separado, depois.', '[{"start":0,"end":10,"role":"predicate_verb","surface":"Let''s take"},{"start":11,"end":15,"role":"direct_object","surface":"this"},{"start":16,"end":24,"role":"adverbial","surface":"offline."}]'::jsonb, '[{"surface":"Let''s","pos":"verb","ipa":"/lɛts/","gloss":"vamos"},{"surface":"take","pos":"verb","ipa":"/teɪk/","gloss":"pegar, levar"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"offline","pos":"adverb","ipa":"/ˌɔːfˈlaɪn/","gloss":"fora da reunião"}]'::jsonb),
  ('unit-work-b1-01-09', 'lesson-work-b1-01', 9, 'sentence', 'What are the next steps?', 'Quais são os próximos passos?', '/wʌt ɑːr ðə nɛkst stɛps/', 'Fechar a reunião com ações.', '[{"start":0,"end":4,"role":"predicate_adj","surface":"What"},{"start":5,"end":8,"role":"predicate_verb","surface":"are"},{"start":9,"end":24,"role":"subject","surface":"the next steps?"}]'::jsonb, '[{"surface":"What","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"next","pos":"adjective","ipa":"/nɛkst/","gloss":"próximo"},{"surface":"steps","pos":"noun","ipa":"/stɛps/","gloss":"passos"}]'::jsonb),
  ('unit-work-b1-01-10', 'lesson-work-b1-01', 10, 'sentence', 'Thanks, everyone. Talk soon.', 'Obrigado, pessoal. Até logo.', '/θæŋks ˈɛvriwʌn tɔːk suːn/', 'Encerramento informal.', '[{"start":0,"end":17,"role":"discourse_marker","surface":"Thanks, everyone."},{"start":18,"end":28,"role":"predicate_verb","surface":"Talk soon."}]'::jsonb, '[{"surface":"Thanks","pos":"interjection","ipa":"/θæŋks/","gloss":"obrigado, valeu"},{"surface":"everyone","pos":"pronoun","ipa":"/ˈɛvriwʌn/","gloss":"todo mundo, pessoal"},{"surface":"Talk","pos":"verb","ipa":"/tɔːk/","gloss":"falar"},{"surface":"soon","pos":"adverb","ipa":"/suːn/","gloss":"logo"}]'::jsonb)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations)
VALUES
  ('unit-work-b1-02-01', 'lesson-work-b1-02', 1, 'sentence', 'Just following up on my last email.', 'Só retomando meu último e-mail.', '/dʒʌst ˈfɑːloʊɪŋ ʌp ɑːn maɪ læst ˈiːmeɪl/', '"Follow up" = cobrar com educação.', '[{"start":0,"end":17,"role":"predicate_verb","surface":"Just following up"},{"start":18,"end":35,"role":"adverbial","surface":"on my last email."}]'::jsonb, '[{"surface":"Just","pos":"adverb","ipa":"/dʒʌst/","gloss":"só, apenas"},{"surface":"following","pos":"verb","ipa":"/ˈfɑːloʊɪŋ/","gloss":"retomando (follow up)"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"last","pos":"adjective","ipa":"/læst/","gloss":"último"},{"surface":"email","pos":"noun","ipa":"/ˈiːmeɪl/","gloss":"e-mail"}]'::jsonb),
  ('unit-work-b1-02-02', 'lesson-work-b1-02', 2, 'sentence', 'Please find the file attached.', 'Segue o arquivo em anexo.', '/pliːz faɪnd ðə faɪl əˈtætʃt/', 'Fórmula fixa de e-mail.', '[{"start":0,"end":11,"role":"predicate_verb","surface":"Please find"},{"start":12,"end":20,"role":"direct_object","surface":"the file"},{"start":21,"end":30,"role":"predicate_adj","surface":"attached."}]'::jsonb, '[{"surface":"Please","pos":"adverb","ipa":"/pliːz/","gloss":"por favor"},{"surface":"find","pos":"verb","ipa":"/faɪnd/","gloss":"encontrar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"file","pos":"noun","ipa":"/faɪl/","gloss":"arquivo"},{"surface":"attached","pos":"adjective","ipa":"/əˈtætʃt/","gloss":"anexado"}]'::jsonb),
  ('unit-work-b1-02-03', 'lesson-work-b1-02', 3, 'sentence', 'Let me know if you have any questions.', 'Me avisa se tiver alguma dúvida.', '/lɛt miː noʊ ɪf juː hæv ˈɛni ˈkwɛstʃənz/', 'Fechamento comum de e-mail.', '[{"start":0,"end":11,"role":"predicate_verb","surface":"Let me know"},{"start":12,"end":38,"role":"adverbial","surface":"if you have any questions."}]'::jsonb, '[{"surface":"Let","pos":"verb","ipa":"/lɛt/","gloss":"deixar, permitir"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"know","pos":"verb","ipa":"/noʊ/","gloss":"saber"},{"surface":"if","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"any","pos":"determiner","ipa":"/ˈɛni/","gloss":"algum, alguma"},{"surface":"questions","pos":"noun","ipa":"/ˈkwɛstʃənz/","gloss":"perguntas, dúvidas"}]'::jsonb),
  ('unit-work-b1-02-04', 'lesson-work-b1-02', 4, 'sentence', 'I''ll get back to you by Friday.', 'Te dou um retorno até sexta.', '/aɪl ɡɛt bæk tuː juː baɪ ˈfraɪdeɪ/', '"Get back to" = responder depois.', '[{"start":0,"end":13,"role":"predicate_verb","surface":"I''ll get back"},{"start":14,"end":20,"role":"adverbial","surface":"to you"},{"start":21,"end":31,"role":"adverbial","surface":"by Friday."}]'::jsonb, '[{"surface":"I''ll","pos":"pronoun","ipa":"/aɪl/","gloss":"eu vou"},{"surface":"get","pos":"verb","ipa":"/ɡɛt/","gloss":"conseguir, chegar"},{"surface":"back","pos":"adverb","ipa":"/bæk/","gloss":"de volta"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"by","pos":"preposition","ipa":"/baɪ/","gloss":"até (prazo)"},{"surface":"Friday","pos":"proper noun","ipa":"/ˈfraɪdeɪ/","gloss":"sexta-feira"}]'::jsonb),
  ('unit-work-b1-02-05', 'lesson-work-b1-02', 5, 'sentence', 'Can we push the deadline to Monday?', 'Dá pra adiar o prazo pra segunda?', '/kæn wiː pʊʃ ðə ˈdɛdlaɪn tuː ˈmʌndeɪ/', '"Push" = adiar.', '[{"start":0,"end":3,"role":"predicate_verb","surface":"Can"},{"start":4,"end":6,"role":"subject","surface":"we"},{"start":7,"end":11,"role":"predicate_verb","surface":"push"},{"start":12,"end":24,"role":"direct_object","surface":"the deadline"},{"start":25,"end":35,"role":"adverbial","surface":"to Monday?"}]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"push","pos":"verb","ipa":"/pʊʃ/","gloss":"adiar, empurrar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"deadline","pos":"noun","ipa":"/ˈdɛdlaɪn/","gloss":"prazo"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"Monday","pos":"proper noun","ipa":"/ˈmʌndeɪ/","gloss":"segunda-feira"}]'::jsonb),
  ('unit-work-b1-02-06', 'lesson-work-b1-02', 6, 'sentence', 'Sorry for the late reply.', 'Desculpa a demora pra responder.', '/ˈsɑːri fɔːr ðə leɪt rɪˈplaɪ/', 'Abertura quando você atrasou.', '[{"start":0,"end":5,"role":"discourse_marker","surface":"Sorry"},{"start":6,"end":25,"role":"adverbial","surface":"for the late reply."}]'::jsonb, '[{"surface":"Sorry","pos":"adjective","ipa":"/ˈsɑːri/","gloss":"desculpa"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"late","pos":"adjective","ipa":"/leɪt/","gloss":"atrasado"},{"surface":"reply","pos":"noun","ipa":"/rɪˈplaɪ/","gloss":"resposta"}]'::jsonb),
  ('unit-work-b1-02-07', 'lesson-work-b1-02', 7, 'sentence', 'I''m swamped this week.', 'Tô atolado essa semana.', '/aɪm swɑːmpt ðɪs wiːk/', '"Swamped" = sobrecarregado.', '[{"start":0,"end":3,"role":"subject","surface":"I''m"},{"start":4,"end":11,"role":"predicate_adj","surface":"swamped"},{"start":12,"end":22,"role":"adverbial","surface":"this week."}]'::jsonb, '[{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"swamped","pos":"adjective","ipa":"/swɑːmpt/","gloss":"atolado"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"week","pos":"noun","ipa":"/wiːk/","gloss":"semana"}]'::jsonb),
  ('unit-work-b1-02-08', 'lesson-work-b1-02', 8, 'sentence', 'Thanks for the heads-up.', 'Valeu pelo aviso.', '/θæŋks fɔːr ðə ˈhɛdz ʌp/', '"Heads-up" = aviso prévio.', '[{"start":0,"end":6,"role":"discourse_marker","surface":"Thanks"},{"start":7,"end":24,"role":"adverbial","surface":"for the heads-up."}]'::jsonb, '[{"surface":"Thanks","pos":"interjection","ipa":"/θæŋks/","gloss":"obrigado, valeu"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"heads-up","pos":"noun","ipa":"/ˈhɛdz ʌp/","gloss":"aviso prévio"}]'::jsonb),
  ('unit-work-b1-02-09', 'lesson-work-b1-02', 9, 'sentence', 'That works for me.', 'Por mim tá ótimo.', '/ðæt wɜːrks fɔːr miː/', 'Confirmar data ou proposta.', '[{"start":0,"end":4,"role":"subject","surface":"That"},{"start":5,"end":10,"role":"predicate_verb","surface":"works"},{"start":11,"end":18,"role":"adverbial","surface":"for me."}]'::jsonb, '[{"surface":"That","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"works","pos":"verb","ipa":"/wɜːrks/","gloss":"funciona, serve"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"}]'::jsonb),
  ('unit-work-b1-02-10', 'lesson-work-b1-02', 10, 'sentence', 'Looking forward to working with you.', 'Ansioso pra trabalhar com você.', '/ˈlʊkɪŋ ˈfɔːrwərd tuː ˈwɜːrkɪŋ wɪð juː/', '"Look forward to" + verbo com -ing.', '[{"start":0,"end":15,"role":"predicate_verb","surface":"Looking forward"},{"start":16,"end":26,"role":"direct_object","surface":"to working"},{"start":27,"end":36,"role":"adverbial","surface":"with you."}]'::jsonb, '[{"surface":"Looking","pos":"verb","ipa":"/ˈlʊkɪŋ/","gloss":"aguardando (look forward)"},{"surface":"forward","pos":"adverb","ipa":"/ˈfɔːrwərd/","gloss":"adiante (look forward)"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"working","pos":"verb","ipa":"/ˈwɜːrkɪŋ/","gloss":"funcionando; trabalhando"},{"surface":"with","pos":"preposition","ipa":"/wɪð/","gloss":"com"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"}]'::jsonb)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations)
VALUES
  ('unit-work-b1-03-01', 'lesson-work-b1-03', 1, 'sentence', 'I''m working on it right now.', 'Tô trabalhando nisso agora mesmo.', '/aɪm ˈwɜːrkɪŋ ɑːn ɪt raɪt naʊ/', '"Right now" reforça o agora.', '[{"start":0,"end":11,"role":"predicate_verb","surface":"I''m working"},{"start":12,"end":17,"role":"adverbial","surface":"on it"},{"start":18,"end":28,"role":"adverbial","surface":"right now."}]'::jsonb, '[{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"working","pos":"verb","ipa":"/ˈwɜːrkɪŋ/","gloss":"funcionando; trabalhando"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"right","pos":"adverb","ipa":"/raɪt/","gloss":"bem; né? (right?)"},{"surface":"now","pos":"adverb","ipa":"/naʊ/","gloss":"agora"}]'::jsonb),
  ('unit-work-b1-03-02', 'lesson-work-b1-03', 2, 'sentence', 'I''m blocked until I get access.', 'Tô travado até conseguir acesso.', '/aɪm blɑːkt ənˈtɪl aɪ ɡɛt ˈæksɛs/', '"Blocked" = impedido de seguir.', '[{"start":0,"end":3,"role":"subject","surface":"I''m"},{"start":4,"end":11,"role":"predicate_adj","surface":"blocked"},{"start":12,"end":31,"role":"adverbial","surface":"until I get access."}]'::jsonb, '[{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"blocked","pos":"adjective","ipa":"/blɑːkt/","gloss":"travado, impedido"},{"surface":"until","pos":"conjunction","ipa":"/ənˈtɪl/","gloss":"até"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"get","pos":"verb","ipa":"/ɡɛt/","gloss":"conseguir, chegar"},{"surface":"access","pos":"noun","ipa":"/ˈæksɛs/","gloss":"acesso"}]'::jsonb),
  ('unit-work-b1-03-03', 'lesson-work-b1-03', 3, 'sentence', 'Do you have a minute to chat?', 'Você tem um minuto pra conversar?', '/duː juː hæv ə ˈmɪnɪt tuː tʃæt/', 'Pedir uma conversa rápida.', '[{"start":0,"end":2,"role":"predicate_verb","surface":"Do"},{"start":3,"end":6,"role":"subject","surface":"you"},{"start":7,"end":11,"role":"predicate_verb","surface":"have"},{"start":12,"end":20,"role":"direct_object","surface":"a minute"},{"start":21,"end":29,"role":"adverbial","surface":"to chat?"}]'::jsonb, '[{"surface":"Do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"minute","pos":"noun","ipa":"/ˈmɪnɪt/","gloss":"minuto"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"chat","pos":"verb","ipa":"/tʃæt/","gloss":"conversar"}]'::jsonb),
  ('unit-work-b1-03-04', 'lesson-work-b1-03', 4, 'sentence', 'Let''s hop on a quick call.', 'Vamos entrar numa call rápida.', '/lɛts hɑːp ɑːn ə kwɪk kɔːl/', '"Hop on" = entrar rapidinho.', '[{"start":0,"end":12,"role":"predicate_verb","surface":"Let''s hop on"},{"start":13,"end":26,"role":"direct_object","surface":"a quick call."}]'::jsonb, '[{"surface":"Let''s","pos":"verb","ipa":"/lɛts/","gloss":"vamos"},{"surface":"hop","pos":"verb","ipa":"/hɑːp/","gloss":"entrar rapidinho (hop on)"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"quick","pos":"adjective","ipa":"/kwɪk/","gloss":"rápido"},{"surface":"call","pos":"noun","ipa":"/kɔːl/","gloss":"chamada, call"}]'::jsonb),
  ('unit-work-b1-03-05', 'lesson-work-b1-03', 5, 'sentence', 'I''ll keep you posted.', 'Vou te mantendo informado.', '/aɪl kiːp juː ˈpoʊstɪd/', '"Keep posted" = manter atualizado.', '[{"start":0,"end":9,"role":"predicate_verb","surface":"I''ll keep"},{"start":10,"end":13,"role":"direct_object","surface":"you"},{"start":14,"end":21,"role":"predicate_adj","surface":"posted."}]'::jsonb, '[{"surface":"I''ll","pos":"pronoun","ipa":"/aɪl/","gloss":"eu vou"},{"surface":"keep","pos":"verb","ipa":"/kiːp/","gloss":"manter"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"posted","pos":"adjective","ipa":"/ˈpoʊstɪd/","gloss":"informado (keep posted)"}]'::jsonb),
  ('unit-work-b1-03-06', 'lesson-work-b1-03', 6, 'sentence', 'It''s almost done, just a few tweaks.', 'Tá quase pronto, só uns ajustes.', '/ɪts ˈɔːlmoʊst dʌn dʒʌst ə fjuː twiːks/', '"Tweak" = pequeno ajuste.', '[{"start":0,"end":4,"role":"subject","surface":"It''s"},{"start":5,"end":17,"role":"predicate_adj","surface":"almost done,"},{"start":18,"end":36,"role":"direct_object","surface":"just a few tweaks."}]'::jsonb, '[{"surface":"It''s","pos":"pronoun","ipa":"/ɪts/","gloss":"é, está"},{"surface":"almost","pos":"adverb","ipa":"/ˈɔːlmoʊst/","gloss":"quase"},{"surface":"done","pos":"adjective","ipa":"/dʌn/","gloss":"pronto, feito"},{"surface":"just","pos":"adverb","ipa":"/dʒʌst/","gloss":"só, apenas"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"few","pos":"determiner","ipa":"/fjuː/","gloss":"poucos"},{"surface":"tweaks","pos":"noun","ipa":"/twiːks/","gloss":"ajustes"}]'::jsonb),
  ('unit-work-b1-03-07', 'lesson-work-b1-03', 7, 'sentence', 'Great job on the presentation.', 'Mandou bem na apresentação.', '/ɡreɪt dʒɑːb ɑːn ðə ˌprɛzənˈteɪʃən/', 'Elogio direto.', '[{"start":0,"end":9,"role":"discourse_marker","surface":"Great job"},{"start":10,"end":30,"role":"adverbial","surface":"on the presentation."}]'::jsonb, '[{"surface":"Great","pos":"adjective","ipa":"/ɡreɪt/","gloss":"ótimo"},{"surface":"job","pos":"noun","ipa":"/dʒɑːb/","gloss":"trabalho"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"presentation","pos":"noun","ipa":"/ˌprɛzənˈteɪʃən/","gloss":"apresentação"}]'::jsonb),
  ('unit-work-b1-03-08', 'lesson-work-b1-03', 8, 'sentence', 'Could you take a look at this?', 'Você pode dar uma olhada nisso?', '/kʊd juː teɪk ə lʊk æt ðɪs/', '"Take a look" = dar uma olhada.', '[{"start":0,"end":5,"role":"predicate_verb","surface":"Could"},{"start":6,"end":9,"role":"subject","surface":"you"},{"start":10,"end":21,"role":"predicate_verb","surface":"take a look"},{"start":22,"end":30,"role":"adverbial","surface":"at this?"}]'::jsonb, '[{"surface":"Could","pos":"auxiliary verb","ipa":"/kʊd/","gloss":"poderia"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"take","pos":"verb","ipa":"/teɪk/","gloss":"pegar, levar"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"look","pos":"noun","ipa":"/lʊk/","gloss":"olhada"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"}]'::jsonb),
  ('unit-work-b1-03-09', 'lesson-work-b1-03', 9, 'sentence', 'I''m logging off for today.', 'Tô saindo por hoje.', '/aɪm ˈlɔːɡɪŋ ɔːf fɔːr təˈdeɪ/', '"Log off" = desconectar, encerrar o dia.', '[{"start":0,"end":15,"role":"predicate_verb","surface":"I''m logging off"},{"start":16,"end":26,"role":"adverbial","surface":"for today."}]'::jsonb, '[{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"logging","pos":"verb","ipa":"/ˈlɔːɡɪŋ/","gloss":"saindo (log off)"},{"surface":"off","pos":"particle","ipa":"/ɔːf/","gloss":"(partícula: off)"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"today","pos":"adverb","ipa":"/təˈdeɪ/","gloss":"hoje"}]'::jsonb),
  ('unit-work-b1-03-10', 'lesson-work-b1-03', 10, 'sentence', 'Have a good weekend, everyone.', 'Bom fim de semana, pessoal.', '/hæv ə ɡʊd ˈwiːkɛnd ˈɛvriwʌn/', 'Despedida de sexta-feira.', '[{"start":0,"end":4,"role":"predicate_verb","surface":"Have"},{"start":5,"end":20,"role":"direct_object","surface":"a good weekend,"},{"start":21,"end":30,"role":"discourse_marker","surface":"everyone."}]'::jsonb, '[{"surface":"Have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"good","pos":"adjective","ipa":"/ɡʊd/","gloss":"bom"},{"surface":"weekend","pos":"noun","ipa":"/ˈwiːkɛnd/","gloss":"fim de semana"},{"surface":"everyone","pos":"pronoun","ipa":"/ˈɛvriwʌn/","gloss":"todo mundo, pessoal"}]'::jsonb)
